solution:
from typing import Optional

def safe_divide(a: float, b: float) -> Optional[float]:
    if b == 0:
        return None
    return a / b

def describe_value(value: int | str | None) -> str:
    if value is None:
        return 'empty'
    if isinstance(value, int):
        return f'number: {value}'
    return f'text: {value}'

