solution:
from typing import Generic, TypeVar, Optional, Callable, TypedDict

T = TypeVar('T')

class CacheStats(TypedDict):
    size: int
    keys: list

class Cache(Generic[T]):
    def __init__(self):
        self._data: dict = {}

    def set(self, key: str, value: T) -> None:
        self._data[key] = value

    def get(self, key: str) -> Optional[T]:
        return self._data.get(key)

    def keys_matching(self, predicate: Callable[[str], bool]) -> list:
        return sorted(k for k in self._data if predicate(k))

    def stats(self) -> CacheStats:
        return {'size': len(self._data), 'keys': sorted(self._data.keys())}
